ReplicatedStorage.Modules.Core.PathResol:
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Workspace = game:GetService("Workspace")

local WORLD_NAME = "World"

local PathResolver = {}

local function root()
	return game:GetService("ReplicatedStorage")
end

local function world()
	return game:GetService("Workspace"):WaitForChild("World")
end

local function waitPath(parent, ...)
	local current = parent
	for _, name in ipairs({ ... }) do
		current = current:WaitForChild(name)
	end
	return current
end

function PathResolver.Root()
	return root()
end

function PathResolver.Assets()
	return waitPath(root(), "Assets")
end

function PathResolver.VehicleCategories()
	if game:GetService("RunService"):IsServer() then return waitPath(game:GetService("ServerStorage"), "Assets", "Vehicles", "Categories") end
	return waitPath(root(), "Assets", "VehiclePreviews", "Categories")
end

function PathResolver.VehicleVFXTemplates()
